import requests

def deny_access(url):
    response = requests.get(url)
    response.raise_for_status()
    return response.status_code == 403

if __name__ == '__main__':
    for url in ['/example-service/', '/protected-endpoint']:
        if deny_access(url):
            print(f"Denied access to {url}")
